=Telegram user message:

{{ $('Normalize Telegram Input').item.json.text }}

Chat ID: {{ $('Normalize Telegram Input').item.json.chat_id }}
User ID: {{ $('Normalize Telegram Input').item.json.user_id }}

Analyze the request and return ONLY valid JSON.

parameters.jsCode:
const raw = String($json.output || $json.text || '').trim();

function parseJson(text) {
  try {
    return JSON.parse(text);
  } catch (_) {}

  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenced) {
    try {
      return JSON.parse(fenced[1]);
    } catch (_) {}
  }

  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try {
      return JSON.parse(text.slice(start, end + 1));
    } catch (_) {}
  }

  return null;
}

const plan = parseJson(raw);
const input = $('Normalize Telegram Input').first().json;

if (!plan || typeof plan !== 'object') {
  return [
    {
      json: {
        ...input,
        master_valid: false,
        master_error: 'Master Agent did not return valid JSON',
        master_raw: raw,
        intent: 'unknown',
        requested_action: 'clarify'
      }
    }
  ];
}

const allowedIntents = [
  'create_song',
  'regenerate_image',
  'regenerate_lyrics',
  'suno_data',
  'generate_video',
  'cancel',
  'unknown'
];

const intent = allowedIntents.includes(plan.intent)
  ? plan.intent
  : 'unknown';

const sourceTypes = [
  'user_provided_text',
  'buddhist_concept',
  'none'
];

const sourceType = sourceTypes.includes(plan.source_type)
  ? plan.source_type
  : 'none';

let nextTasks = Array.isArray(plan.next_tasks)
  ? plan.next_tasks.filter(x => typeof x === 'string')
  : [];

if (intent === 'create_song' && nextTasks.length === 0) {
  nextTasks = ['lyrics', 'image'];
}

if (intent === 'regenerate_lyrics') {
  nextTasks = ['lyrics'];
}

if (intent === 'regenerate_image') {
  nextTasks = ['image'];
}

if (intent === 'generate_video') {
  nextTasks = ['video'];
}

const dependsOn = {
  lyrics: Boolean(plan.depends_on?.lyrics),
  image: Boolean(plan.depends_on?.image),
  video: Boolean(plan.depends_on?.video)
};

return [
  {
    json: {
      ...input,
      master_valid: true,
      master_error: null,
      master_raw: raw,

      intent,
      source_type: sourceType,
      source_text: plan.source_text ?? null,
      concept: plan.concept ?? null,
      language: plan.language ?? null,
      lyrics_style: plan.lyrics_style ?? null,
      visual_direction: plan.visual_direction ?? null,
      requested_action: plan.requested_action ?? null,
      next_tasks: nextTasks,
      depends_on: dependsOn
    }
  }
];

const raw = $json;

// ============================================================
// 1. Resolve input
// ============================================================

// Hỗ trợ cả:
// 1. Input trực tiếp từ Build Production State
// 2. Input sau Read JSON → Extract from File
const data = raw.data || raw;

// Canonical production state
const state = data.production_state || data;

if (!state || typeof state !== 'object') {
  throw new Error('Production state is missing or invalid.');
}

// ============================================================
// 2. Resolve callback
// ============================================================

let callback = null;

try {
  callback = $('Parse Callback').first().json;
} catch (_) {
  callback = null;
}

const run_id = String(
  state.run_id ||
  data.run_id ||
  callback?.run_id ||
  ''
).trim();

if (!run_id) {
  throw new Error('Missing run_id');
}

// ============================================================
// 3. Callback / routing
// ============================================================

const isCallback = Boolean(
  callback?.callback_action ||
  callback?.callback_target ||
  callback?.callback_id ||
  callback?.callback_data
);

const callback_action =
  callback?.callback_action || null;

const callback_target =
  callback?.callback_target || null;

const mode =
  !isCallback
    ? 'initial'
    : callback_action === 'regenerate'
      ? 'regenerate'
      : callback_action === 'generate_video'
        ? 'generate_video'
        : callback_action === 'add_music'
          ? 'add_music'
          : callback_action === 'upload'
            ? 'upload_youtube'
            : callback_action === 'suno_data'
              ? 'suno_data'
              : callback?.mode ||
                callback?.route ||
                'initial';

// ============================================================
// 4. Current lyrics
// ============================================================

const lyricsCurrent =
  state.lyrics?.current || null;

const lyricsTitle =
  String(lyricsCurrent?.title || '').trim();

const lyricsText =
  String(lyricsCurrent?.lyrics || '').trim();

const sunoStyle =
  String(lyricsCurrent?.suno_style || '').trim();

const lyricsVersion =
  Number(
    state.lyrics?.current_version ||
    lyricsCurrent?.version ||
    0
  );

// ============================================================
// 5. Current image
// ============================================================

const image =
  state.image?.current || null;

const imagePath =
  String(image?.path || '').trim();

const imagePrompt =
  String(image?.prompt || '').trim();

const imageVersion =
  Number(
    image?.version ||
    state.image?.current_version ||
    0
  );

// ============================================================
// 6. Video
// ============================================================

const video =
  state.video || {};

const videoPath =
  String(video.path || '').trim();

const videoFilename =
  String(video.filename || '').trim();

const videoPrompt =
  String(video.prompt || '').trim();

const videoDuration =
  Number(video.duration_seconds ?? 5);

// ============================================================
// 7. Audio
// ============================================================

const audio =
  state.audio || {};

const audioPath =
  String(audio.path || '').trim();

const audioFilename =
  String(audio.filename || '').trim();

// ============================================================
// 8. Final video
// ============================================================

const finalVideo =
  state.final_video || {};

const finalVideoPath =
  String(finalVideo.path || '').trim();

const finalVideoFilename =
  String(finalVideo.filename || '').trim();

// ============================================================
// 9. YouTube metadata
// ============================================================

const youtubeMeta =
  state.youtube_meta || {};

const youtubeMetaVersion =
  Number(youtubeMeta.version || 0);

// ============================================================
// 10. Return normalized runtime input
// ============================================================

return [
  {
    json: {
      // ========================================================
      // IDENTIFIERS
      // ========================================================

      run_id,

      chat_id:
        state.chat_id ??
        callback?.chat_id ??
        '',

      message_id:
        state.message_id ??
        callback?.message_id ??
        '',

      user_id:
        state.user_id ??
        null,

      username:
        state.username ??
        null,

      // ========================================================
      // CALLBACK
      // ========================================================

      callback_id:
        callback?.callback_id ??
        null,

      callback_data:
        callback?.callback_data ??
        null,

      callback_action,

      callback_target,

      // ========================================================
      // ROUTING
      // ========================================================

      mode,

      route:
        callback?.route ??
        null,

      // ========================================================
      // PRODUCTION INPUT
      // ========================================================

      intent:
        state.intent ??
        null,

      source_type:
        state.source_type ??
        '',

      source_text:
        state.source_text ??
        '',

      concept:
        state.concept ??
        '',

      language:
        state.language ??
        'Vietnamese',

      lyrics_style:
        state.lyrics_style ??
        '',

      visual_direction:
        state.visual_direction ??
        '',

      requested_action:
        state.requested_action ??
        null,

      // ========================================================
      // LYRICS
      // ========================================================

      title:
        lyricsTitle,

      lyrics:
        lyricsText,

      suno_style:
        sunoStyle,

      lyrics_version:
        lyricsVersion,

      lyrics_current:
        lyricsCurrent,

      lyrics_path:
        String(lyricsCurrent?.path || '').trim(),

      lyrics_word_count:
        Number(lyricsCurrent?.word_count || 0),

      // ========================================================
      // IMAGE
      // ========================================================

      image_prompt:
        imagePrompt,

      image_path:
        imagePath,

      image_version:
        imageVersion,

      image_current:
        image,

      image_filename:
        String(image?.filename || '').trim(),

      image_subfolder:
        String(image?.subfolder || '').trim(),

      image_type:
        String(image?.type || '').trim(),

      image_seed:
        image?.seed ?? null,

      // ========================================================
      // VIDEO
      // ========================================================

      video_path:
        videoPath,

      video_filename:
        videoFilename,

      video_prompt:
        videoPrompt,

      video_duration:
        videoDuration,

      // ========================================================
      // AUDIO
      // ========================================================

      audio_path:
        audioPath,

      audio_filename:
        audioFilename,

      // ========================================================
      // FINAL VIDEO
      // ========================================================

      final_video_path:
        finalVideoPath,

      final_video_filename:
        finalVideoFilename,

      // ========================================================
      // YOUTUBE META
      // ========================================================

      youtube_meta:
        youtubeMeta,

      youtube_title:
        String(youtubeMeta.title || '').trim(),

      youtube_description:
        String(youtubeMeta.description || '').trim(),

      youtube_tags:
        Array.isArray(youtubeMeta.tags)
          ? youtubeMeta.tags
          : [],

      youtube_hashtags:
        Array.isArray(youtubeMeta.hashtags)
          ? youtubeMeta.hashtags
          : [],

      youtube_category_id:
        String(youtubeMeta.category_id || '10'),

      youtube_privacy_status:
        String(youtubeMeta.privacy_status || 'private'),

      youtube_meta_version:
        youtubeMetaVersion,

      // ========================================================
      // YOUTUBE UPLOAD
      // ========================================================

      youtube_upload:
        state.youtube_upload || null,

      youtube_video_id:
        state.youtube_upload?.video_id ||
        null,

      youtube_url:
        state.youtube_upload?.url ||
        null,

      // ========================================================
      // STATUS
      // ========================================================

      status:
        state.status || {},

      // ========================================================
      // FULL CANONICAL STATE
      // ========================================================

      production_state:
        state
    }
  }
];

