}

const title = String(result.title || '').trim();
const lyrics = String(result.lyrics || '').trim();
const suno_style = String(result.suno_style || '').trim();

const wordCount = lyrics
  ? lyrics.split(/\s+/).filter(Boolean).length
  : 0;

const valid = Boolean(title && lyrics && suno_style && wordCount >= 100);

return [
  {
    json: {
      ...input,
      lyrics_valid: valid,
      lyrics_error: valid
        ? null
        : 'Lyrics result is incomplete or too short',
      title,
      lyrics,
      suno_style,
      lyrics_word_count: wordCount,
      lyrics_raw: raw
    }
  }
];

const item = $input.first();

const state = item.json.production_state;

if (!state) {
  throw new Error(
    `Production state not found: ${item.json.run_id || 'unknown run_id'}`
  );
}

// ============================================================
// 1. Resolve current lyrics
// ============================================================

const lyricsCurrent = state.lyrics?.current || null;

const title = String(
  lyricsCurrent?.title || ''
).trim();

const lyrics = String(
  lyricsCurrent?.lyrics || ''
).trim();

const lyricsPath = String(
  lyricsCurrent?.path || ''
).trim();

if (!title) {
  throw new Error(
    `Missing lyrics title: ${state.run_id}`
  );
}

if (!lyrics) {
  throw new Error(
    `Missing lyrics content: ${state.run_id}`
  );
}

if (!lyricsPath) {
  throw new Error(
    `Missing lyrics path: ${state.run_id}`
  );
}

// ============================================================
// 2. Build lyrics text file
// ============================================================

const content = `${title}\n\n${lyrics}\n`;

const filename = lyricsPath
  .split('/')
  .pop();

if (!filename) {
  throw new Error(
    `Invalid lyrics filename: ${lyricsPath}`
  );
}

// ============================================================
// 3. Create binary data
// ============================================================

item.binary = item.binary || {};

item.binary.data =
  await this.helpers.prepareBinaryData(
    Buffer.from(content, 'utf8'),
    filename,
    'text/plain; charset=utf-8'
  );

// ============================================================
// 4. Return item
// ============================================================

return [item];

const input = $('Update Lyrics State').first().json;

// ============================================================
// Load current production state from JSON-file workflow
// ============================================================

const state = input.production_state;

if (!state) {
  throw new Error(
    `Production state not found in Update Lyrics State: ${input.run_id || 'unknown run_id'}`
  );
}

const run_id = String(
  input.run_id ||
  state.run_id ||
  ''
);

if (!run_id) {
  throw new Error('Missing run_id');
}

// ============================================================
// Update lyrics persistence metadata
// ============================================================

state.lyrics_saved = true;
state.lyrics_path =
  input.lyrics_path ||
  state.lyrics_path ||
  null;

state.lyrics_version =
  Number(input.lyrics_version || state.lyrics_version || 0);

state.updated_at = new Date().toISOString();

// ============================================================
// Return updated state
// This output goes to:
// Update → Convert to File → Write JSON
// ============================================================

return [
  {
    json: {
      ...input,

      run_id,

      production_state: state,

      lyrics_saved: true,

      lyrics_path: state.lyrics_path,

      lyrics_version: state.lyrics_version,

      status: 'lyrics_ready'
    }
  }
];

const input = $('Mark Lyrics Saved').first().json;

return [
  {
    json: {
      run_id: input.run_id,
      chat_id: input.chat_id,
      title: input.title,
      lyrics: input.lyrics,
      suno_style: input.suno_style,
      lyrics_word_count: input.lyrics_word_count,
      lyrics_version: input.lyrics_version,
      lyrics_path: input.lyrics_path,
      mode: input.mode,
      status: 'lyrics_ready'
    }
  }
];

