const input = $json;

// ============================================================
// 1. Resolve production state
// ============================================================

const state = input.production_state;

if (!state || typeof state !== 'object') {
  throw new Error(
    `Production state not found: ${input.run_id || 'unknown run_id'}`
  );
}

const run_id = String(
  input.run_id ||
  state.run_id ||
  ''
).trim();

if (!run_id) {
  throw new Error('Missing run_id');
}

// ============================================================
// 2. Preserve Telegram / runtime context
// ============================================================

const chat_id =
  input.chat_id ??
  state.chat_id ??
  '';

const message_id =
  input.message_id ??
  state.message_id ??
  null;

const user_id =
  input.user_id ??
  state.user_id ??
  null;

const username =
  input.username ??
  state.username ??
  null;

const callback_id =
  input.callback_id ??
  null;

const callback_data =
  input.callback_data ??
  null;

const callback_action =
  input.callback_action ??
  null;

const callback_target =
  input.callback_target ??
  null;

// ============================================================
// 3. Determine next image version from canonical state
// ============================================================

const previousImage = state.image || {};

const previousVersions = Array.isArray(previousImage.versions)
  ? previousImage.versions
  : [];

const previousVersion = Number(
  previousImage.current_version || 0
);

const version =
  Math.max(
    previousVersion,
    previousVersions.length
  ) + 1;

const now = new Date().toISOString();

// ============================================================
// 4. Build new image version record
// ============================================================

const imageRecord = {
  version,

  filename:
    input.output_filename ||
    null,

  subfolder:
    input.output_subfolder ||
    null,

  type:
    input.output_type ||
    null,

  path:
    input.image_local_path ||
    null,

  seed:
    input.seed ??
    null,

  prompt:
    input.image_prompt ||
    null,

  mode:
    input.mode ||
    'initial',

  created_at:
    now
};

if (!imageRecord.path) {
  throw new Error(
    `Missing image_local_path for run_id: ${run_id}`
  );
}

// ============================================================
// 5. Update canonical IMAGE state
// ============================================================

state.image = {
  current_version: version,

  current: imageRecord,

  versions: [
    ...previousVersions,
    imageRecord
  ]
};

// ============================================================
// 6. Update canonical STATUS
// ============================================================

state.status = state.status || {};

state.status.image = 'ready';

// ============================================================
// 7. Update canonical timestamp
// ============================================================

state.updated_at = now;

// ============================================================
// 8. Ensure canonical identity remains intact
// ============================================================

state.run_id = run_id;

if (!state.chat_id && chat_id !== '') {
  state.chat_id = chat_id;
}

if (!state.message_id && message_id !== null) {
  state.message_id = message_id;
}

if (!state.user_id && user_id !== null) {
  state.user_id = user_id;
}

if (!state.username && username !== null) {
  state.username = username;
}

// ============================================================
// 9. Return FULL runtime context
// ============================================================
//
// production_state = canonical state
// Các field bên ngoài = runtime / Telegram context
//
// Save State chỉ serialize:
// $json.production_state
// ============================================================

return [
  {
    json: {
      // -----------------------------
      // Identity
      // -----------------------------
      run_id,

      chat_id,
      message_id,
      user_id,
      username,

      // -----------------------------
      // Callback context
      // -----------------------------
      callback_id,
      callback_data,
      callback_action,
      callback_target,

      // -----------------------------
      // Image result
      // -----------------------------
      image_saved: true,

      image_version: version,

      image_local_path:
        imageRecord.path,

      output_filename:
        imageRecord.filename,

      output_subfolder:
        imageRecord.subfolder,

      output_type:
        imageRecord.type,

      image_seed:
        imageRecord.seed,

      image_prompt:
        imageRecord.prompt,

      // -----------------------------
      // Canonical state
      // -----------------------------
      production_state: state
    },

    // -----------------------------
    // Preserve generated image binary
    // -----------------------------
    binary:
      $('Prepare Image Asset').first().binary
  }
];

