if (!raw) {
  throw new Error('YouTube Meta Agent returned no output.');
}

// ============================================================
// 1. Parse Agent output
// ============================================================

let meta;

if (typeof raw === 'object' && raw !== null) {
  meta = raw;
} else {
  const text = String(raw)
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    meta = JSON.parse(text);
  } catch (error) {
    throw new Error('YouTube Meta Agent did not return valid JSON.');
  }
}

if (!meta || typeof meta !== 'object' || Array.isArray(meta)) {
  throw new Error('YouTube metadata must be a JSON object.');
}

// ============================================================
// 2. Resolve production state
// ============================================================

const source = $('Prepare YouTube Meta').first().json;

const state = source.production_state;

if (!state) {
  throw new Error(
    `Production state not found: ${source.run_id || 'unknown run_id'}`
  );
}

const run_id = String(
  source.run_id ||
  state.run_id ||
  ''
).trim();

const chat_id = source.chat_id;

if (!run_id) {
  throw new Error('Missing run_id while saving YouTube metadata.');
}

// ============================================================
// 3. Validate title
// ============================================================

if (typeof meta.title !== 'string' || !meta.title.trim()) {
  throw new Error('YouTube metadata title is missing.');
}

const title = meta.title.trim();

if (title.length > 100) {
  throw new Error(
    `YouTube title exceeds 100 characters: ${title.length}`
  );
}

// ============================================================
// 4. Validate description
// ============================================================

if (
  typeof meta.description !== 'string' ||
  !meta.description.trim()
) {
  throw new Error('YouTube metadata description is missing.');
}

const description = meta.description.trim();

if (description.length > 5000) {
  throw new Error('YouTube description is unexpectedly long.');
}

// ============================================================
// 5. Validate tags
// ============================================================

if (!Array.isArray(meta.tags)) {
  throw new Error('YouTube metadata tags must be an array.');
}

const tags = [
  ...new Set(
    meta.tags
      .map(v => String(v ?? '').trim())
      .filter(Boolean)
  )
];

if (tags.length < 3 || tags.length > 15) {
  throw new Error(
    `Invalid number of YouTube tags: ${tags.length}`
  );
}

const totalTagLength = tags.join(',').length;

if (totalTagLength > 450) {
  throw new Error(
    `YouTube tags are too long: ${totalTagLength} characters.`
  );
}

// ============================================================
// 6. Validate hashtags
// ============================================================

if (!Array.isArray(meta.hashtags)) {
  throw new Error(
    'YouTube metadata hashtags must be an array.'
  );
}

const hashtags = [
  ...new Set(
    meta.hashtags
      .map(v => String(v ?? '').trim())
      .filter(Boolean)
      .map(v =>
        v.startsWith('#')
          ? v
          : `#${v.replace(/^#+/, '')}`
      )
  )
];

if (hashtags.length < 3 || hashtags.length > 5) {
  throw new Error(
    `Invalid number of YouTube hashtags: ${hashtags.length}`
  );
}

for (const hashtag of hashtags) {
  if (!/^#[^\s#]+$/.test(hashtag)) {
    throw new Error(`Invalid hashtag: ${hashtag}`);
  }
}

// ============================================================
// 7. Validate category + privacy
// ============================================================

const category_id = String(
  meta.category_id || '10'
);

const privacy_status = String(
  meta.privacy_status || 'private'
);

if (!/^\d+$/.test(category_id)) {
  throw new Error(
    `Invalid YouTube category_id: ${category_id}`
  );
}

if (
  !['private', 'unlisted', 'public'].includes(
    privacy_status
  )
) {
  throw new Error(
    `Invalid YouTube privacy_status: ${privacy_status}`
  );
}

// ============================================================
// 8. Generate metadata version
// ============================================================

const previousVersion = Number(
  state.youtube_meta?.version || 0
);

const version = previousVersion + 1;

const generated_at = new Date().toISOString();

// ============================================================
// 9. Build canonical YouTube metadata
// ============================================================

const youtube_meta = {
  version,
  title,
  description,
  tags,
  hashtags,
  category_id,
  privacy_status,
  generated_at
};

// ============================================================
// 10. Update canonical production state
// ============================================================

state.run_id = run_id;

state.youtube_meta = youtube_meta;

state.status = state.status || {};
state.status.youtube_meta = 'ready';

state.updated_at = generated_at;

// ============================================================
// 11. Return runtime envelope
//
// Save State after this node must write ONLY:
// $json.production_state
// ============================================================

return [
  {
    json: {
      ...source,

      run_id,
      chat_id,

      production_state: state,

      youtube_meta,
      youtube_meta_version: version,

      state_saved: false
    }
  }
];

