parameters.jsCode:
const input = $json;

// ============================================================
// DSV - TELEGRAM NORMALIZER
// ============================================================
// Supports:
//   1. Normal Telegram messages
//   2. Telegram callback_query
//
// Callback formats:
//   regenerate:lyrics:<run_id>
//   regenerate:image:<run_id>
//   suno_data:<run_id>
//   generate_video:image:<run_id>
//   add_music:<run_id>
//   regenerate:youtube_meta:<run_id>
//   upload:youtube:<run_id>
// ============================================================

const message = input.message || null;
const callback = input.callback_query || null;

// ------------------------------------------------------------
// CALLBACK QUERY
// ------------------------------------------------------------
if (callback) {
  const data = String(callback.data || '').trim();
  const from = callback.from || {};
  const callbackMessage = callback.message || {};
  const chat = callbackMessage.chat || {};

  let callback_action = null;
  let callback_target = null;
  let run_id = null;

  let match;

  // regenerate:lyrics:<run_id>
  // regenerate:image:<run_id>
  match = data.match(/^regenerate:(lyrics|image):(.+)$/);
  if (match) {
    callback_action = 'regenerate';
    callback_target = match[1];
    run_id = match[2];
  }

  // suno_data:<run_id>
  if (!callback_action) {
    match = data.match(/^suno_data:(.+)$/);
    if (match) {
      callback_action = 'suno_data';
      callback_target = 'lyrics';
      run_id = match[1];
    }
  }

  // generate_video:image:<run_id>
  if (!callback_action) {
    match = data.match(/^generate_video:image:(.+)$/);
    if (match) {
      callback_action = 'generate_video';
      callback_target = 'image';
      run_id = match[1];
    }
  }

  // add_music:<run_id>
  if (!callback_action) {
    match = data.match(/^add_music:(.+)$/);
    if (match) {
      callback_action = 'add_music';
      callback_target = 'audio';
      run_id = match[1];
    }
  }

  // regenerate:youtube_meta:<run_id>
  if (!callback_action) {
    match = data.match(/^regenerate:youtube_meta:(.+)$/);
    if (match) {
      callback_action = 'regenerate_youtube_meta';
      callback_target = 'youtube';
      run_id = match[1];
    }
  }

  // upload:youtube:<run_id>
  if (!callback_action) {
    match = data.match(/^upload:youtube:(.+)$/);
    if (match) {
      callback_action = 'upload_youtube';
      callback_target = 'youtube';
      run_id = match[1];
    }
  }

  // ----------------------------------------------------------
  // Validate callback
  // ----------------------------------------------------------
  if (!callback.id) {
    throw new Error('Normalize Telegram Input: callback_query.id is missing.');
  }

  if (!data) {
    throw new Error('Normalize Telegram Input: callback_query.data is missing.');
  }

  if (!callback_action || !callback_target || !run_id) {
    throw new Error(`Normalize Telegram Input: unsupported callback_data: ${data}`);
  }

  return [
    {
      json: {
        input_type: 'callback_query',
        is_callback: true,
        is_message: false,

        callback_query_id: String(callback.id),
        callback_id: String(callback.id),
        callback_data: data,

        callback_action,
        callback_target,

        // Canonical callback run identifier.
        run_id,
        callback_run_id: run_id,

        chat_id: chat.id ?? null,
        callback_chat_id: chat.id ?? null,

        message_id: callbackMessage.message_id ?? null,
        callback_message_id: callbackMessage.message_id ?? null,

        user_id: from.id ?? null,
        username: from.username || null,
        first_name: from.first_name || null,
        last_name: from.last_name || null,

        text: '',

        raw_message: callbackMessage,
        raw_callback_query: callback,

        received_at: new Date().toISOString()
      }
    }
  ];
}

// ------------------------------------------------------------
// NORMAL MESSAGE
// ------------------------------------------------------------
if (message) {
  const from = message.from || {};
  const chat = message.chat || {};
  const text = String(message.text || message.caption || '').trim();

  return [
    {
      json: {
        input_type: 'message',
        is_callback: false,
        is_message: true,

        callback_query_id: null,
        callback_id: null,
        callback_data: null,
        callback_action: null,
        callback_target: null,
        run_id: null,
        callback_run_id: null,

        chat_id: chat.id ?? null,
        callback_chat_id: null,

        message_id: message.message_id ?? null,
        callback_message_id: null,

        user_id: from.id ?? null,
        username: from.username || null,
        first_name: from.first_name || null,
        last_name: from.last_name || null,

        text,

        raw_message: message,
        raw_callback_query: null,

        has_text: Boolean(text),
        has_photo: Array.isArray(message.photo) && message.photo.length > 0,
        has_audio: Boolean(message.audio),
        has_voice: Boolean(message.voice),
        has_document: Boolean(message.document),
        has_video: Boolean(message.video),

        received_at: new Date().toISOString()
      }
    }
  ];
}

// ------------------------------------------------------------
// UNKNOWN UPDATE
// ------------------------------------------------------------
return [
  {
    json: {
      input_type: 'unknown',
      is_callback: false,
      is_message: false,

      callback_query_id: null,
      callback_id: null,
      callback_data: null,
      callback_action: 'unknown',
      callback_target: null,
      run_id: null,
      callback_run_id: null,

      chat_id: null,
      callback_chat_id: null,
      message_id: null,
      callback_message_id: null,

      user_id: null,
      username: null,
      first_name: null,
      last_name: null,

      text: '',
      raw_message: null,
      raw_callback_query: null,

      received_at: new Date().toISOString()
    }
  }
];

const input = $json;

// ============================================================
// DSV - PARSE CALLBACK
// ============================================================
// Normalize Telegram Input has already parsed the callback.
// This node intentionally keeps the existing workflow structure
// and validates/canonicalizes the callback fields.
//
// IMPORTANT:
// No new run_id is created here.
// The existing run_id is the production identifier.
// ============================================================

const callback_id = String(
  input.callback_id ?? input.callback_query_id ?? ''
).trim();

const callback_data = String(
  input.callback_data ?? ''
).trim();

const callback_action = String(
  input.callback_action ?? ''
).trim();

const callback_target = String(
  input.callback_target ?? ''
).trim();

const run_id = String(
  input.run_id ?? input.callback_run_id ?? ''
).trim();

if (!callback_id) {
  throw new Error(
    'Parse Callback: callback id is missing.'
  );
}

if (!callback_data) {
  throw new Error(
    'Parse Callback: callback data is missing.'
  );
}

if (!callback_action || !callback_target || !run_id) {
  throw new Error(
    `Parse Callback: invalid callback context. data=${callback_data}`
  );
}

return [
  {
    json: {
      ...input,

      callback_id,
      callback_query_id: callback_id,
      callback_data,

      callback_action,
      callback_target,

      // Canonical production identifier.
      run_id,
      callback_run_id: run_id,

      callback_chat_id: input.callback_chat_id ?? input.chat_id ?? null,
      callback_message_id: input.callback_message_id ?? input.message_id ?? null
    }
  }
];

const parsed = $('Parse Callback').item.json;

// ============================================================
// RESTORE CALLBACK CONTEXT
// ============================================================
// Telegram - Answer Callback is an HTTP Request node.
// Its output is Telegram's API response and therefore replaces
// the previous $json context.
//
// Restore the original parsed callback context so every router
// IF node receives callback_action / callback_target / run_id.
//
// IMPORTANT:
// No state is created or modified here.
// No run_id is generated here.
// ============================================================

return [
  {
    json: {
      ...parsed,
      callback_acknowledged: true,
      callback_acknowledged_at: new Date().toISOString()
    }
  }
];

const input = $json;

// ============================================================
// 1. Resolve production state
// ============================================================

const raw = input.data || input;
const state = raw.production_state || raw;

const run_id = String(
  input.run_id ||
  raw.run_id ||
  state.run_id ||
  ''
).trim();

if (!run_id) {
  throw new Error('Missing run_id');
}

// ============================================================
// 2. Resolve generated lyrics
// ============================================================

const title = String(
  input.title ||
  raw.title ||
  ''
).trim();

const lyrics = String(
  input.lyrics ||
  raw.lyrics ||
  ''
).trim();

const suno_style = String(
  input.suno_style ||
  input.style ||
  raw.suno_style ||
  state.lyrics?.current?.suno_style ||
  ''
).trim();

if (!title) {
  throw new Error(`Missing title for lyrics regeneration: ${run_id}`);
}

if (!lyrics) {
  throw new Error(`Missing lyrics for lyrics regeneration: ${run_id}`);
}

// ============================================================
// 3. Existing lyrics versions
// ============================================================

const previousLyrics = state.lyrics || {};

const previousVersions = Array.isArray(previousLyrics.versions)
  ? previousLyrics.versions
  : [];

const previousCurrentVersion = Number(
  previousLyrics.current_version || 0
);

const currentVersion =
  Math.max(
    previousCurrentVersion,
    previousVersions.length
  ) + 1;

const versionName = String(currentVersion).padStart(3, '0');

const lyricsPath =
  `/data/productions/${run_id}-lyrics-v${versionName}.txt`;

const now = new Date().toISOString();

// ============================================================
// 4. Build lyrics version
// ============================================================

const versionRecord = {
  version: currentVersion,
  path: lyricsPath,
  title,
  lyrics,
  suno_style,
  word_count: Number(input.lyrics_word_count || 0),
  mode: input.mode || 'regenerate',
  created_at: now
};

// ============================================================
// 5. Update canonical production state
// ============================================================

state.run_id = run_id;

state.lyrics = {
  current_version: currentVersion,
  current: versionRecord,
  versions: [
    ...previousVersions,
    versionRecord
  ]
};

// ============================================================
// 6. Update status
// ============================================================

state.status = state.status || {};
state.status.lyrics = 'ready';
state.updated_at = now;

// ============================================================
// 7. Return state + runtime metadata
// ============================================================

return [
  {
    json: {
      ...input,
      run_id,
      production_state: state,

      // Runtime-only metadata.
      // These are NOT persisted because Save State writes
      // only production_state.
      lyrics_version: currentVersion,
      lyrics_version_name: versionName,
      lyrics_path: lyricsPath,
      lyrics_created_at: now,

      state_saved: false
    }
  }
];

const x = $json;
const state = x.production_state || null;

if (!state) {
  throw new Error(
    `Production state not found for SUNO DATA: ${x.run_id || 'unknown run_id'}`
  );
}

const run_id = String(x.run_id || state.run_id || '').trim();

if (!run_id) {
  throw new Error('Missing run_id for SUNO DATA');
}

const lyricsCurrent = state.lyrics?.current || null;

const title = String(lyricsCurrent?.title || '').trim();
const style = String(lyricsCurrent?.suno_style || '').trim();
const lyrics = String(lyricsCurrent?.lyrics || '').trim();
const language = String(state.language || 'Vietnamese').trim();

if (!title) {
  throw new Error(`Missing Suno title for run_id: ${run_id}`);
}

if (!lyrics) {
  throw new Error(`Missing Suno lyrics for run_id: ${run_id}`);
}

const escapeHtml = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

// Chống style dài tràn ngang Telegram.
// Tự động xuống dòng theo khoảng trắng, không phá nội dung.
const wrapText = (text, maxLength = 75) => {
  const words = String(text || '').split(/\s+/);
  const lines = [];
  let line = '';

  for (const word of words) {
    if (!line) {
      line = word;
      continue;
    }

    if ((line + ' ' + word).length <= maxLength) {
      line += ' ' + word;
    } else {
      lines.push(line);
      line = word;
    }
  }

  if (line) {
    lines.push(line);
  }

  return lines.join('\n');
};

const styleWrapped = wrapText(style, 53);

const suno = {
  title,
  style,
  lyrics,
  language,
  custom_mode: true,
  instrumental: false
};

const suno_copy_text = [
  `Title: ${title}`,
  `Style: ${style || '(not specified)'}`,
  '',
  'Lyrics:',
  lyrics
].join('\n');

const telegram_text = [
  'ㅤ𝄂𝄚𝅦𝄚ㅤ <b>SUNO DATA</b>',
  '',
  `<b>Title:</b> ${escapeHtml(title)}`,
  '',
  '<b>Style:</b>',
  `<pre>${escapeHtml(styleWrapped || '(not specified)')}</pre>`,
  '',
  `<b>Language:</b> ${escapeHtml(language)}`,
  '',
  '<b>Lyrics:</b>',
  `<pre>${escapeHtml(lyrics)}</pre>`
].join('\n');

return [{
  json: {
    ...x,
    run_id,
    production_state: state,

    suno,
    suno_json: JSON.stringify(suno, null, 2),
    suno_copy_text,

    telegram_text,

    suno_title: title,
    suno_style: style,
    suno_lyrics: lyrics,
    suno_language: language
  }
}];
